      c.budget3 = Math.min(30, (c.budget3 == null ? 30 : c.budget3) + (Date.now() - (c.last3 || Date.now())) * 0.015); c.last3 = Date.now();
      if ((c.budget3 -= 1) < 0 || typeof m.d !== 'string' || m.d.length > 3000 || !/^[A-Za-z0-9+/=]+$/.test(m.d)) return;
