// drop dead connections every 30 s
setInterval(() => {
  for (const c of clients) {
    if (!c.alive) { c.socket.destroy(); continue; }
    c.alive = false;
    try { c.socket.write(frame(9, Buffer.alloc(0))); } catch {}
  }
}, 30000).unref();

// ---------------- automatic updates ----------------
// The server can keep itself up to date from a GitHub repository. Set it once, either here in UPDATE_URL, or in a file
// called update.json next to this file:   { "url": "https://raw.githubusercontent.com/OWNER/REPO/main/release/latest.json" }
// (optional: "token": "github token" for a private repo, "check_minutes": 10, "enabled": false to switch it off).
// latest.json says which build is newest, where its app.js is, and its SHA-256. A new build is downloaded, checked
// (size, SHA-256, a test start), the old file is kept as server.js.bak, and the server restarts when no one is playing.
const BUILD = 'ac1ad75fddef';
const UPDATE_URL = "https://raw.githubusercontent.com/Cooliguy/Marrow/main/release/latest.json";
const UP = { last: null, result: 'waiting for the first check', pending: null };
function upConf() {
  let c = {}; try { c = JSON.parse(fs.readFileSync(path.join(__dirname, 'update.json'), 'utf8')); } catch {}
  const url = process.env.MARROW_UPDATE_URL || c.url || (UPDATE_URL.startsWith('__') ? '' : UPDATE_URL);
  return { url, token: process.env.MARROW_UPDATE_TOKEN || c.token || '', every: Math.max(2, +(c.check_minutes || 10)), on: c.enabled !== false && !!url };
}
function upGet(url, token, asBuffer, hops = 0) {
  return new Promise((resolve, reject) => {
    const u = new URL(url);
    const local = u.protocol === 'http:' && process.env.MARROW_UPDATE_ALLOW_HTTP === '1' && /^(localhost|127\.0\.0\.1)$/.test(u.hostname);
    if (u.protocol !== 'https:' && !local) return reject(new Error('updates are only downloaded over https'));
    const mod = u.protocol === 'https:' ? require('https') : http;
    const req = mod.get(u, { headers: { 'user-agent': 'marrow-server', ...(token ? { authorization: 'token ' + token } : {}), 'cache-control': 'no-cache' }, timeout: 60000 }, (r) => {
      if ([301, 302, 303, 307, 308].includes(r.statusCode) && r.headers.location && hops < 4) { r.resume(); return resolve(upGet(new URL(r.headers.location, u).href, token, asBuffer, hops + 1)); }
      if (r.statusCode !== 200) { r.resume(); return reject(new Error('HTTP ' + r.statusCode + ' for ' + u.pathname)); }
      const parts = []; let n = 0; r.on('data', (d) => { n += d.length; if (n > 200e6) { req.destroy(); reject(new Error('too large')); } else parts.push(d); });
      r.on('end', () => { const b = Buffer.concat(parts); resolve(asBuffer ? b : b.toString('utf8')); });
    });
    req.on('timeout', () => req.destroy(new Error('timed out'))); req.on('error', reject);
  });
}
async function upCheck() {
  const c = upConf(); if (!c.on) { UP.result = c.url ? 'switched off' : 'not set up'; return; }
  UP.last = new Date().toISOString();
  try {
    if (UP.pending) { upRestartWhenQuiet(); return; }
    const L = JSON.parse(await upGet(c.url + (c.url.includes('?') ? '&' : '?') + 't=' + Date.now(), c.token));
    if (!L.build || L.build === BUILD) { await upTeaser(L, c); UP.result = 'up to date' + (UP.teaser ? ' (' + UP.teaser + ')' : ''); return; }
    await upTeaser(L, c);                          // the video first, so the new pages never point at a file that is not there yet
    const appUrl = new URL(L.url || 'app.js', c.url).href;
    const buf = await upGet(appUrl, c.token, true);
    if (L.size && buf.length !== L.size) throw new Error('download incomplete');
    if (crypto.createHash('sha256').update(buf).digest('hex') !== String(L.sha256 || '').toLowerCase()) throw new Error('SHA-256 does not match, not installing');
    const tmp = __filename + '.download';
    fs.writeFileSync(tmp, buf);
    const cp = require('child_process'), t = cp.spawnSync(process.execPath, [tmp], { env: { ...process.env, MARROW_SELFTEST: '1' }, timeout: 60000, encoding: 'utf8' });
    if (t.status !== 0 || !/selftest ok/.test(t.stdout || '')) { fs.unlinkSync(tmp); throw new Error('new build failed its test start'); }
    try { fs.copyFileSync(__filename, __filename + '.bak'); } catch {}
    fs.renameSync(tmp, __filename);
    UP.pending = L.build; UP.result = 'build ' + L.build + ' installed, restarting when no one is playing';
    console.log('update: ' + UP.result);
    upRestartWhenQuiet();
  } catch (e) { UP.result = 'check failed: ' + e.message; console.log('update: ' + UP.result); }
}
// the teaser video can ride along in a release: latest.json "teaser": { "url", "size", "sha256" }
let teaserSum = null;   // { key: size+mtime, sha }
function localTeaserSha() {
  const tz = findTeaser(); if (!tz) return null;
  const st = fs.statSync(tz.f), key = st.size + ':' + st.mtimeMs;
  if (!teaserSum || teaserSum.key !== key) teaserSum = { key, sha: crypto.createHash('sha256').update(fs.readFileSync(tz.f)).digest('hex') };
  return teaserSum.sha;
}
async function upTeaser(L, c) {
  const T = L.teaser; if (!T || !T.sha256) return;
  if (localTeaserSha() === String(T.sha256).toLowerCase()) { UP.teaser = 'teaser current'; return; }
  const buf = await upGet(new URL(T.url || 'teaser.mp4', c.url).href, c.token, true);
  if ((T.size && buf.length !== T.size) || crypto.createHash('sha256').update(buf).digest('hex') !== String(T.sha256).toLowerCase()) throw new Error('teaser download does not match, not installing');
  const dst = path.join(__dirname, 'teaser.mp4'), tmp = dst + '.download';
  fs.writeFileSync(tmp, buf); fs.renameSync(tmp, dst); teaserSum = null;
  UP.teaser = 'new teaser installed'; console.log('update: new teaser installed (' + (buf.length / 1048576).toFixed(1) + ' MB)');
}
let upWaitSince = 0;
function upRestartWhenQuiet() {
  if (!upWaitSince) upWaitSince = Date.now();
  const quiet = clients.size === 0, tooLong = Date.now() - upWaitSince > 3 * 3600e3;   // never wait more than 3 hours
  if (!quiet && !tooLong) return;
  console.log('update: restarting into build ' + UP.pending);
  if (!process.env.pm_id) {   // not under PM2: start the new server ourselves; it waits until this one has let go of the port
    try { require('child_process').spawn(process.execPath, [__filename], { cwd: __dirname, env: process.env, detached: true, stdio: 'ignore' }).unref(); } catch {}
  }
  server.close(); setTimeout(() => process.exit(0), 300);
}
function upStart() { const c = upConf(); UP.result = c.on ? 'waiting for the first check' : (c.url ? 'switched off' : 'not set up yet (see update.json in DEPLOY.md)'); setTimeout(upCheck, +process.env.MARROW_UPDATE_FIRST_MS || 20000).unref(); setInterval(upCheck, c.every * 60000).unref(); setInterval(() => { if (UP.pending) upRestartWhenQuiet(); }, 60000).unref(); }

if (process.env.MARROW_SELFTEST === '1') { console.log('selftest ok ' + BUILD + ' ' + GAME_HTML.length + ' ' + SITE.size); process.exit(0); }
// start listening; if the port is still held by the previous version (just after an update), keep trying for 30 s
let listenTries = 0;
server.on('error', (e) => { if (e.code === 'EADDRINUSE' && listenTries++ < 60) return setTimeout(() => server.listen(PORT), 500); console.error(e.message); process.exit(1); });
server.listen(PORT, () => { console.log('MARROW build ' + BUILD + ' running on port ' + PORT); upStart(); });

